using System.Collections.Generic; public sealed class FinalAccusationController:ValidatedPuzzleController { private string suspect;private readonly HashSet<string> evidence=new();protected override void ResetPuzzle(){suspect=null;evidence.Clear();}public void Accuse(string suspectId,IEnumerable<string> evidenceIds){suspect=suspectId;evidence.Clear();if(evidenceIds!=null)foreach(string id in evidenceIds)evidence.Add(id);}public bool Submit(string expectedSuspect,string[] requiredEvidence){if(suspect!=expectedSuspect)return false;if(requiredEvidence!=null)foreach(string id in requiredEvidence)if(!evidence.Contains(id))return false;return CompleteWhen(true,suspect); } }
